Lemma call_edge_ok : forall f r g, In (f, r, g) CALL_EDGES -> call_edgeb f r g = true.
Proof.
  intros f r g H. assert (X : forallb (fun e => call_edgeb (fst (fst e)) (snd (fst e)) (snd e)) CALL_EDGES = true) by (vm_compute; reflexivity).
  exact (proj1 (forallb_forall _ _) X _ H).
Qed.
Lemma tail_edge_ok : forall f g, In (f, g) TAIL_EDGES -> tail_edgeb f g = true.
